66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
77	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
84	     * new owner's id, customerCode, registrationDate and membershipLevel.
85	     */
86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    /**
89	     * Common street-type abbreviations expanded during address normalization, keyed by the
90	     * upper-cased abbreviation.
91	     */
92	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
93	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
94	
95	    /**
96	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
97	     * city already holds this many owners.
98	     */
99	    private static final int CITY_CAPACITY = 50;
100	
101	    /**
102	     * Maximum number of owners that may be created on a single day. A create is rejected once this
103	     * many owners already carry the current day as their {@code registrationDate}.
104	     */
105	    private static final int DAILY_OWNER_LIMIT = 100;
106	
107	    private final ClinicService clinicService;
108	
109	    private final OwnerMapper ownerMapper;
110	
111	    private final PetMapper petMapper;
112	
113	    private final VisitMapper visitMapper;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        validateRequiredFields(ownerFieldsDto);
154	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
158	        rejectFutureRegistrationDate(owner.getRegistrationDate());
159	        LocalDate effectiveDate = owner.getRegistrationDate() == null
160	            ? LocalDate.now()
161	            : owner.getRegistrationDate();
162	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
163	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
164	        rejectWhenCityAtCapacity(owner.getCity());
165	        applyHousehold(owner);
166	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
167	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
168	        rejectDuplicateIdentity(owner);
169	        owner.setCustomerCode(customerCode(owner));
170	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
171	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
172	        flagPossibleDuplicate(owner);
173	        this.clinicService.saveOwner(owner);
174	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
175	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
176	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
177	            ownerDto.getMembershipLevel());
178	        headers.setLocation(UriComponentsBuilder.newInstance()
179	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
180	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    /**
184	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
185	     * code derived from the owner's postcode (falling back to the city-to-region table, then
186	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
187	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}). The
188	     * code is a pure function of the owner's region and identity, carrying no sequence number.
189	     *
190	     * @param owner the owner being created, with its normalized telephone already applied
191	     * @return the assigned customer code
192	     */
193	    private String customerCode(Owner owner) {
194	        return regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
195	    }
196	
197	    /**
198	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
199	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
200	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
201	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
202	     * postcode nor the city identifies a region.
203	     *
204	     * @param owner the owner being created
205	     * @return the derived region code, never {@code null}
206	     */
207	    private String regionCode(Owner owner) {
208	        String fromPostcode = regionFromPostcode(owner.getPostcode());
209	        if (fromPostcode != null) {
210	            return fromPostcode;
211	        }
212	        String fromCity = region(owner.getCity());
213	        return fromCity == null ? "UNKNOWN" : fromCity;
214	    }
215	
216	    /**
217	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
218	     * postcode is absent, not 4 digits, or in no known range.
219	     *
220	     * @param postcode the owner's postcode, may be {@code null}
221	     * @return the region code, or {@code null} when no known range contains the postcode
222	     */
223	    private String regionFromPostcode(String postcode) {
224	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
225	            return null;
226	        }
227	        int value = Integer.parseInt(postcode);
228	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
229	            int[] range = entry.getValue();
230	            if (value >= range[0] && value <= range[1]) {
231	                return entry.getKey();
232	            }
233	        }
234	        return null;
235	    }
236	
237	    /**
238	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
239	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
240	     *
241	     * @param telephone the owner's normalized (E.164) telephone
242	     * @param lastName  the owner's last name
243	     * @return the 8-character upper-cased hex hash
244	     */
245	    private String identityHash8(String telephone, String lastName) {
246	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
247	        try {
248	            byte[] digest = MessageDigest.getInstance("SHA-256")
249	                .digest(input.getBytes(StandardCharsets.UTF_8));
250	            StringBuilder hex = new StringBuilder(digest.length * 2);
251	            for (byte b : digest) {
252	                hex.append(String.format("%02x", b));
253	            }
254	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
255	        } catch (NoSuchAlgorithmException ex) {
256	            throw new IllegalStateException("SHA-256 not available", ex);
257	        }
258	    }
259	
260	    /**
261	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
262	     * last two digits of the registrationDate year, zero-padded (e.g. {@code NSW-1A2B3C4D-M26}).
263	     *
264	     * @param customerCode     the owner's assigned customer code
265	     * @param registrationDate the owner's registration date
266	     * @return the assigned membership number
267	     */
268	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
269	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
270	    }
271	
272	    /**
273	     * Counts the existing owners that already share the given firstName and lastName, compared
274	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
275	     * the owners that pre-existed this create.
276	     *
277	     * @param firstName the new owner's first name
278	     * @param lastName  the new owner's last name
279	     * @return the number of existing namesakes
280	     */
281	    private int countNamesakes(String firstName, String lastName) {
282	        return (int) this.clinicService.findAllOwners().stream()
283	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
284	                && equalsIgnoreCase(existing.getLastName(), lastName))
285	            .count();
286	    }
287	
288	    /**
289	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
290	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
291	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
292	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
293	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
294	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
295	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
296	     *
297	     * @param owner the owner being created, with its normalized telephone already applied
298	     */
299	    private void flagPossibleDuplicate(Owner owner) {
300	        Owner match = findPossibleDuplicate(owner);
301	        if (match != null) {
302	            owner.setPossibleDuplicate(true);
303	            owner.setPossibleDuplicateOf(match.getId());
304	        } else {
305	            owner.setPossibleDuplicate(false);
306	            owner.setPossibleDuplicateOf(null);
307	        }
308	    }
309	
310	    /**
311	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
312	     * postcode, but a different telephone. When several existing owners match, the one with the
313	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
314	     * postcode or no such existing owner exists.
315	     *
316	     * @param owner the owner being created
317	     * @return the matching existing owner, or {@code null} when there is no soft-match
318	     */
319	    private Owner findPossibleDuplicate(Owner owner) {
320	        if (isBlank(owner.getPostcode())) {
321	            return null;
322	        }
323	        return this.clinicService.findAllOwners().stream()
324	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
325	                && owner.getPostcode().equals(existing.getPostcode())
326	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
327	            .min(Comparator.comparing(Owner::getId))
328	            .orElse(null);
329	    }
330	
331	    /**
332	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
333	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
334	     * customer-code sequence is derived.
335	     *
336	     * @param city the new owner's city
337	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
338	     */
339	    private void rejectWhenCityAtCapacity(String city) {
340	        long count = this.clinicService.findAllOwners().stream()
341	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
342	            .count();
343	        if (count >= CITY_CAPACITY) {
344	            throw new CityAtCapacityException(city);
345	        }
346	    }
347	
348	    /**
349	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
350	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
351	     * business-day registration date, so the limit is enforced per business day and weekend
352	     * requests count against the Monday they roll forward to.
353	     *
354	     * @param registrationDate the owner's adjusted (business-day) registration date
355	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
356	     *                                  registration date
357	     */
358	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
359	        long count = this.clinicService.findAllOwners().stream()
360	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
361	            .count();
362	        if (count >= DAILY_OWNER_LIMIT) {
363	            throw new DailyOwnerLimitException(registrationDate);
364	        }
365	    }
366	
367	    /**
368	     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
369	     * later than the current server date. A {@code null} registration date is accepted (it defaults
370	     * to the server date) and today or any past date is allowed; only a future value is rejected.
371	     *
372	     * @param registrationDate the registration date supplied on the request, may be {@code null}
373	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
374	     */
375	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
376	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
377	            throw new FutureRegistrationDateException(registrationDate);
378	        }
379	    }
380	
381	    /**
382	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
383	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
384	     * effective registration date (whether supplied in the request or defaulted to the server date)
385	     * so a weekend value never persists as an owner's {@code registrationDate}.
386	     *
387	     * @param date the effective registration date
388	     * @return the same date when it is a weekday, otherwise the next Monday
389	     */
390	    private LocalDate toBusinessDay(LocalDate date) {
391	        return switch (date.getDayOfWeek()) {
392	            case SATURDAY -> date.plusDays(2);
393	            case SUNDAY -> date.plusDays(1);
394	            default -> date;
395	        };
396	    }
397	
398	    private boolean equalsIgnoreCase(String a, String b) {
399	        return a == null ? b == null : a.equalsIgnoreCase(b);
400	    }
401	
402	    /**
403	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
404	     * offending field so the client learns about all of them at once.
405	     *
406	     * @param ownerFieldsDto the submitted owner fields
407	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
408	     *                                     missing or blank
409	     */
410	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
411	        List<String> errors = new ArrayList<>();
412	        if (isBlank(ownerFieldsDto.getFirstName())) {
413	            errors.add("firstName");
414	        }
415	        if (isBlank(ownerFieldsDto.getLastName())) {
416	            errors.add("lastName");
417	        }
418	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
419	            errors.add("address");
420	        }
421	        if (isBlank(ownerFieldsDto.getCity())) {
422	            errors.add("city");
423	        }
424	        if (isBlank(ownerFieldsDto.getTelephone())) {
425	            errors.add("telephone");
426	        }
427	        if (!errors.isEmpty()) {
428	            throw new MissingOwnerFieldsException(errors);
429	        }
430	    }
431	
432	    private boolean isBlank(String value) {
433	        return value == null || value.isBlank();
434	    }
435	
436	    /**
437	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
438	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
439	     */
440	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
441	        "NSW", new int[] {2000, 2099},
442	        "VIC", new int[] {3000, 3099},
443	        "QLD", new int[] {4000, 4099});
444	
445	    /**
446	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
447	     * is optional and accepted, keeping the create contract backward-compatible. When present the
448	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
449	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
450	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
451	     *
452	     * @param postcode the raw postcode value as submitted, may be {@code null}
453	     * @param city     the owner's city, used to resolve the region whose range applies
454	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
455	     *                                  the city's region
456	     */
457	    private void validatePostcode(String postcode, String city) {
458	        if (isBlank(postcode)) {
459	            return;
460	        }
461	        if (!postcode.matches("[0-9]{4}")) {
462	            throw new InvalidPostcodeException(postcode, city);
463	        }
464	        String region = region(city);
465	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
466	        if (range != null) {
467	            int value = Integer.parseInt(postcode);
468	            if (value < range[0] || value > range[1]) {
469	                throw new InvalidPostcodeException(postcode, city);
470	            }
471	        }
472	    }
473	
474	    /**
475	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
476	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
477	     *
478	     * @param city the owner's city
479	     * @return the region code, or {@code null} when the city has no known region
480	     */
481	    private String region(String city) {
482	        if (city == null) {
483	            return null;
484	        }
485	        return switch (city) {
486	            case "Sydney" -> "NSW";
487	            case "Melbourne" -> "VIC";
488	            case "Brisbane" -> "QLD";
489	            default -> null;
490	        };
491	    }
492	
493	    /**
494	     * The number of national (subscriber) digits an E.164 number must carry for a given country
495	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
496	     * national digits and the North American Numbering Plan ('+1') requires 10.
497	     */
498	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
499	        Map.of("61", 9, "1", 10);
500	
501	    /**
502	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
503	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
504	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
505	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
506	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
507	     *
508	     * @param telephone the raw telephone value as submitted
509	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
510	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
511	     *                                   national-number length is wrong for its country code
512	     */
513	    private String normalizeTelephone(String telephone) {
514	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
515	        String nationalSignificantNumber;
516	        if (cleaned.startsWith("+")) {
517	            nationalSignificantNumber = cleaned.substring(1);
518	        } else {
519	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
520	            nationalSignificantNumber = "61" + national;
521	        }
522	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
523	            throw new InvalidTelephoneException(telephone);
524	        }
525	        validateNationalNumberLength(nationalSignificantNumber, telephone);
526	        return "+" + nationalSignificantNumber;
527	    }
528	
529	    /**
530	     * Validates the national-number length of an E.164 number against its country calling code. The
531	     * significant number is a country code immediately followed by the national digits; for each
532	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
533	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
534	     * left unchecked.
535	     *
536	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
537	     * @param rejectedValue             the raw telephone value, reported on rejection
538	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
539	     */
540	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
541	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
542	            String countryCode = rule.getKey();
543	            if (nationalSignificantNumber.startsWith(countryCode)) {
544	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
545	                if (nationalDigits != rule.getValue()) {
546	                    throw new InvalidTelephoneException(rejectedValue);
547	                }
548	                return;
549	            }
550	        }
551	    }
552	
553	    /**
554	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
555	     * value is treated as absent and returns {@code null}); when present the value must be a
556	     * syntactically valid address, and is stored and returned lower-cased.
557	     *
558	     * @param email the raw email value as submitted, may be {@code null}
559	     * @return the lower-cased email, or {@code null} when none was supplied
560	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
561	     */
562	    private String normalizeEmail(String email) {
563	        if (email == null || email.isBlank()) {
564	            return null;
565	        }
566	        String normalized = email.trim().toLowerCase();
567	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
568	            throw new InvalidEmailException(email);
569	        }
570	        return normalized;
571	    }
572	
573	    /**
574	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
575	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
576	     * key is the normalized telephone, email and householdId joined together, this one check
577	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
578	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
579	     * with different telephones have different keys and are both allowed.
580	     *
581	     * @param owner the owner being created, with its normalized telephone, email and householdId
582	     *              already applied
583	     * @throws DuplicateIdentityException if another owner already has the same identityKey
584	     */
585	    private void rejectDuplicateIdentity(Owner owner) {
586	        String identityKey = identityKey(owner);
587	        boolean inUse = this.clinicService.findAllOwners().stream()
588	            .map(this::identityKey)
589	            .anyMatch(identityKey::equals);
590	        if (inUse) {
591	            throw new DuplicateIdentityException(identityKey);
592	        }
593	    }
594	
595	    /**
596	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
597	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
598	     * duplicate decision is made by comparing whole identityKeys.
599	     *
600	     * @param owner the owner whose identityKey to derive
601	     * @return the derived identityKey
602	     */
603	    private String identityKey(Owner owner) {
604	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
605	        String email = owner.getEmail() == null ? "" : owner.getEmail();
606	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
607	        return telephone + "|" + email + "|" + householdId;
608	    }
609	
610	    /**
611	     * Applies the household rule to an owner being created. An owner belongs to the same household
612	     * as an existing owner when their lastName and address both match (compared case-insensitively
613	     * with runs of whitespace collapsed to a single space).
614	     *
615	     * <p>When no such existing owner exists there is nothing to do. Otherwise the new owner and
616	     * every existing owner in the household are assigned the same stable
617	     * {@link #householdId(String, String) householdId}. The household itself is no longer a
618	     * rejection: duplicate detection is now decided solely by the whole {@code identityKey}, of
619	     * which the householdId is one segment, so two members of the same household with different
620	     * telephones have different keys and are both allowed.
621	     *
622	     * @param owner the owner being created
623	     */
624	    private void applyHousehold(Owner owner) {
625	        String lastNameKey = toHouseholdKey(owner.getLastName());
626	        String addressKey = toHouseholdKey(owner.getAddress());
627	        List<Owner> household = this.clinicService.findAllOwners().stream()
628	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
629	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
630	            .toList();
631	        if (household.isEmpty()) {
632	            return;
633	        }
634	        String householdId = householdId(lastNameKey, addressKey);
635	        owner.setHouseholdId(householdId);
636	        for (Owner existing : household) {
637	            if (!householdId.equals(existing.getHouseholdId())) {
638	                existing.setHouseholdId(householdId);
639	                this.clinicService.saveOwner(existing);
640	            }
641	        }
642	    }
643	
644	    /**
645	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
646	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
647	     * lastName and address keys. Being a pure function of the household, every owner in it derives
648	     * the same value regardless of creation order.
649	     *
650	     * @param lastNameKey the normalized household lastName key
651	     * @param addressKey  the normalized household address key
652	     * @return the household identifier
653	     */
654	    private String householdId(String lastNameKey, String addressKey) {
655	        try {
656	            byte[] digest = MessageDigest.getInstance("SHA-256")
657	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
658	            StringBuilder hex = new StringBuilder(digest.length * 2);
659	            for (byte b : digest) {
660	                hex.append(String.format("%02x", b));
661	            }
662	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
663	        } catch (NoSuchAlgorithmException ex) {
664	            throw new IllegalStateException("SHA-256 not available", ex);
665	        }
666	    }
667	
668	    /**
669	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
670	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
671	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
672	     * string.
673	     */
674	    private String toHouseholdKey(String value) {
675	        if (value == null) {
676	            return "";
677	        }
678	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
679	    }
680	
681	    /**
682	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
683	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
684	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
685	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
686	     * value, or one that is blank once trimmed, normalizes to an empty string.
687	     *
688	     * @param address the raw address value as submitted, may be {@code null}
689	     * @return the normalized address, or an empty string when none was supplied
690	     */
691	    private String normalizeAddress(String address) {
692	        if (address == null) {
693	            return "";
694	        }
695	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
696	        if (collapsed.isEmpty()) {
697	            return "";
698	        }
699	        String[] tokens = collapsed.split(" ");
700	        StringBuilder normalized = new StringBuilder(collapsed.length());
701	        for (int i = 0; i < tokens.length; i++) {
702	            if (i > 0) {
703	                normalized.append(' ');
704	            }
705	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
706	        }
707	        return normalized.toString();
708	    }
709	
710	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
711	    @Override
712	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
713	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
714	        if (currentOwner == null) {
715	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
716	        }
717	        currentOwner.setAddress(ownerFieldsDto.getAddress());
718	        currentOwner.setCity(ownerFieldsDto.getCity());
719	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
720	        currentOwner.setLastName(ownerFieldsDto.getLastName());
721	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
722	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
723	        this.clinicService.saveOwner(currentOwner);
724	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
725	    }
726	
727	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
728	    @Transactional
729	    @Override
730	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
731	        Owner owner = this.clinicService.findOwnerById(ownerId);
732	        if (owner == null) {
733	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
734	        }
735	        this.clinicService.deleteOwner(owner);
736	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
737	    }
738	
739	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
740	    @Override
741	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
742	        Owner owner = this.clinicService.findOwnerById(ownerId);
743	        if (owner == null) {
744	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
745	        }
746	        HttpHeaders headers = new HttpHeaders();
747	        Pet pet = petMapper.toPet(petFieldsDto);
748	        owner.setId(ownerId);
749	        pet.setOwner(owner);
750	        pet.getType().setName(null);
751	        this.clinicService.savePet(pet);
752	        PetDto petDto = petMapper.toPetDto(pet);
753	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
754	            .buildAndExpand(pet.getId()).toUri());
755	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
756	    }
757	
758	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
759	    @Override
760	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
761	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
762	        if (currentOwner != null) {
763	            Pet currentPet = this.clinicService.findPetById(petId);
764	            if (currentPet != null) {
765	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
766	                currentPet.setName(petFieldsDto.getName());
767	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
768	                this.clinicService.savePet(currentPet);
769	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
770	            }
771	        }
772	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
773	    }
774	
775	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
776	    @Override
777	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
778	        HttpHeaders headers = new HttpHeaders();
779	        Visit visit = visitMapper.toVisit(visitFieldsDto);
780	        Pet pet = new Pet();
781	        pet.setId(petId);
782	        visit.setPet(pet);
783	        this.clinicService.saveVisit(visit);
784	        VisitDto visitDto = visitMapper.toVisitDto(visit);
785	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
786	            .buildAndExpand(visit.getId()).toUri());
787	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
788	    }
789	
790	
791	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
792	    @Override
793	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
794	        Owner owner = this.clinicService.findOwnerById(ownerId);
795	        if (owner != null) {
796	            Pet pet = owner.getPet(petId);
797	            if (pet != null) {
798	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
799	            }
800	        }
801	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
802	    }
803	}
